param(
  [string]$Serial = "${BEHCS_DEVICE_SERIAL}",
  [int]$Port = 8789,
  [switch]$WriteProofPacket
)

$ErrorActionPreference = "Stop"

& adb -s $Serial forward "tcp:$Port" "tcp:$Port" | Out-Null

$status = & curl.exe -s --max-time 5 "http://127.0.0.1:$Port/api/status" | ConvertFrom-Json
if (-not ($status -and $status.ok)) { throw "OMNICODER status failed" }

$packetResult = $null
if ($WriteProofPacket.IsPresent) {
  $proof = @{
    pilot = "acer-pilot-agent"
    target = "falcon-omnicoder-smoke"
    lane = "white_room"
    language = "markdown"
    title = "OMNICODER smoke packet"
    objective = "Verify Falcon OMNICODER writes a white-room packet through the visual frontend backend."
    code = "# smoke`nOMNICODER write path is alive."
    command = "review_packet_only"
    notes = "Generated by Test-FalconOmnicoder.ps1"
  } | ConvertTo-Json -Compress
  $tmp = Join-Path $env:TEMP ("omnicoder-proof-" + [guid]::NewGuid().ToString("N") + ".json")
  try {
    [System.IO.File]::WriteAllText($tmp, $proof, [System.Text.UTF8Encoding]::new($false))
    $packetResult = & curl.exe -s --max-time 10 -X POST "http://127.0.0.1:$Port/api/packet" -H "Content-Type: application/json" --data-binary "@$tmp" | ConvertFrom-Json
  } finally {
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
  }
  $status = & curl.exe -s --max-time 5 "http://127.0.0.1:$Port/api/status" | ConvertFrom-Json
}

[pscustomobject]@{
  ok = $true
  service = $status.service
  serial = $Serial
  acer_url = "http://127.0.0.1:$Port/"
  white_room_count = $status.white_room.count
  packets_count = $status.packets.count
  inbox_count = $status.inbox.count
  room40_count = $status.room40.count
  proof_packet_id = if ($packetResult) { $packetResult.packet.id } else { $null }
}
